package controller;
import dao.*;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import model.*;import java.io.IOException;import java.math.*;import java.util.*;
@WebServlet(name="AdminPurchaseController",urlPatterns={"/admin/purchases"})
public class AdminPurchaseController extends HttpServlet{
 private final PurchaseOrderDAO dao=new PurchaseOrderDAO();private final SupplierDAO suppliers=new SupplierDAO();private final IngredientDAO ingredients=new IngredientDAO();private final RestockRequestDAO requests=new RestockRequestDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{if(!ScaffoldAccess.requireAdmin(r,p))return;move(r,"purchaseMessage");move(r,"purchaseError");try{r.setAttribute("purchaseOrders",dao.findAll("ALL"));r.setAttribute("activeSuppliers",suppliers.getActiveSuppliers());r.setAttribute("allIngredients",ingredients.getActiveIngredientsWithDetails());r.setAttribute("approvedRequests",requests.getRestockRequests("APPROVED"));r.getRequestDispatcher("/admin-purchases.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{if(!ScaffoldAccess.requireAdmin(r,p))return;r.setCharacterEncoding("UTF-8");HttpSession s=r.getSession();User u=(User)s.getAttribute("user");String action=trim(r.getParameter("action"));try{boolean ok=true;if("create".equals(action)){BigDecimal qty=new BigDecimal(r.getParameter("quantity"));BigDecimal total=new BigDecimal(r.getParameter("totalPrice"));if(qty.signum()<=0||total.signum()<0)throw new IllegalArgumentException("Số lượng và tổng tiền không hợp lệ.");PurchaseOrder po=new PurchaseOrder();po.setSupplierId(Integer.parseInt(r.getParameter("supplierId")));po.setCreatorId(u.getId());String rr=trim(r.getParameter("restockRequestId"));if(!rr.isEmpty())po.setRestockRequestId(Integer.parseInt(rr));po.setNote(trim(r.getParameter("note")));PurchaseOrderItem item=new PurchaseOrderItem(Integer.parseInt(r.getParameter("ingredientId")),qty,total.divide(qty,2,RoundingMode.HALF_UP));dao.create(po,List.of(item));}else{int id=Integer.parseInt(r.getParameter("id"));if("order".equals(action))ok=dao.updateStatus(id,"ORDERED");else if("cancel".equals(action))ok=dao.updateStatus(id,"CANCELLED");else if("receive".equals(action))ok=dao.receiveIntoInventory(id);else throw new IllegalArgumentException("Thao tác không hợp lệ.");}if(ok)s.setAttribute("purchaseMessage","Đã cập nhật phiếu nhập hàng.");else s.setAttribute("purchaseError","Không thể cập nhật vì trạng thái phiếu đã thay đổi.");}catch(Exception e){getServletContext().log("Purchase action failed",e);s.setAttribute("purchaseError",e.getMessage());}p.sendRedirect(r.getContextPath()+"/admin/purchases");}
 private void move(HttpServletRequest r,String k){Object v=r.getSession().getAttribute(k);if(v!=null){r.setAttribute(k,v);r.getSession().removeAttribute(k);}}private String trim(String v){return v==null?"":v.trim();}
}
